@RestController
@RequestMapping(value = "customer/contacts")
@ExposesResourceFor(ContactsDTO.class)
@Secured({"ROLE_USER"})
public class ContactsRestController {
	private final ContactsService contactsService;
	private final ContactsDtoAssembler contactsDtoAssembler = new ContactsDtoAssembler();

	public ContactsRestController(ContactsService contactsService) {
		this.contactsService = contactsService;
	}

	/**
	 * Viewing contacts.
	 */
	@GetMapping
	public ContactsDTO getContacts(Principal principal) {
		Contacts contacts = contactsService.getContacts(principal.getName());
		return toDto(contacts);
	}

	/**
	 * Updating contacts.
	 *
	 * @return updated contacts
	 */
	@PutMapping
	public ContactsDTO updateContacts(Principal principal, @RequestBody @Valid ContactsDTO contactsDto) {
		String login = principal.getName();
		Contacts changedContacts = contactsDtoAssembler.toDomain(contactsDto);
		contactsService.updateUserContacts(changedContacts, login);
		return toDto(changedContacts);
	}

	private ContactsDTO toDto(Contacts changedContacts) {
		ContactsDTO dto = contactsDtoAssembler.toModel(changedContacts);
		dto.add(linkTo(CartRestController.class).withRel("Shopping cart"));
		return dto;
	}
}

@RestController
@RequestMapping(value = "products")
@ExposesResourceFor(ProductDTO.class)
public class ProductsRestController {

	private final ProductService productService;
	private final ProductDtoAssembler productAssembler = new ProductDtoAssembler();

	public ProductsRestController(ProductService productService) {
		this.productService = productService;
	}

	/**
	 * All the existing products, sorted by id.
	 */
	@GetMapping
	public Collection<ProductDTO> getProducts() {
		return productService.findAll().stream()
			.sorted(Comparator.comparing(Product::getId))
			.map(productAssembler::toModel)
			.peek(this::addSelfLink)
			.collect(Collectors.toList());
	}

	private void addSelfLink(ProductDTO dto) {
		dto.add(linkTo(methodOn(getClass()).getProduct(dto.getProductId())).withRel("self"));
	}

	/**
	 * Viewing a single product.
	 *
	 * @return product with the specified id
	 * @throws UnknownEntityException if the product with the specified id doesn't exist
	 */
	@GetMapping(value = "/{productId}")
	public ProductDTO getProduct(@PathVariable long productId) {
		return productService.findById(productId)
			.map(productAssembler::toModel)
			.map(this::addListLink)
			.orElseThrow(() -> new UnknownEntityException(ProductDTO.class, productId));
	}

	private ProductDTO addListLink(ProductDTO dto) {
		dto.add(linkTo(methodOn(getClass()).getProducts()).withRel("All products"));
		return dto;
	}
}

@Entity
@Table(name = "cart")
public class Cart implements Serializable {
	private static final long serialVersionUID = -6884843696895527904L;

	@Id
	@Column(name = "id", unique = true, nullable = false)
	@GeneratedValue(generator = "gen")
	@GenericGenerator(name = "gen", strategy = "foreign", parameters = @Parameter(name = "property", value = "userAccount"))
	private long id;

	@OneToOne
	@PrimaryKeyJoinColumn
	private UserAccount userAccount;

	@OneToMany(fetch = FetchType.EAGER, cascade = CascadeType.ALL, orphanRemoval = true,
		targetEntity = CartItem.class, mappedBy = "cart")
	private List<CartItem> cartItems = new ArrayList<>(0);

	@Column(name = "delivery_included", nullable = false)
	private boolean deliveryIncluded = true;

	public Cart() {
		this(null);
	}

	public Cart(UserAccount userAccount) {
		this.userAccount = userAccount;
	}

	public boolean isEmpty() {
		return cartItems.isEmpty();
	}

	public CartItem update(Product product, int newQuantity) {
		if (product == null)
			return null;

		CartItem updatedItem = null;
		if (newQuantity > 0) {
			CartItem existingItem = findItem(product.getId());
			if (existingItem == null) {
				CartItem newItem = new CartItem(this, product, newQuantity);
				cartItems.add(newItem);
				updatedItem = newItem;
			} else {
				existingItem.setQuantity(newQuantity);
				updatedItem = existingItem;
			}
		} else {
			removeItem(product.getId());
		}
		return updatedItem;
	}

	private void removeItem(long productId) {
		cartItems.removeIf(item -> item.getProduct().getId() == productId);
	}

	private CartItem findItem(long productId) {
		for (CartItem existingItem : cartItems) {
			if (existingItem.getProduct().getId() == productId)
				return existingItem;
		}
		return null;
	}

	private double calculateItemsCost() {
		return cartItems.stream()
			.mapToDouble(CartItem::calculateCost)
			.sum();
	}

	public void clear() {
		cartItems.clear();
	}

	public long getId() {
		return id;
	}

	public void setId(long id) {
		this.id = id;
	}

	public UserAccount getUserAccount() {
		return userAccount;
	}

	public void setUserAccount(UserAccount userAccount) {
		this.userAccount = userAccount;
	}

	public List<CartItem> getCartItems() {
		return Collections.unmodifiableList(cartItems);
	}

	public boolean isDeliveryIncluded() {
		return deliveryIncluded;
	}

	public void setDeliveryIncluded(boolean deliveryIncluded) {
		this.deliveryIncluded = deliveryIncluded;
	}

	public int getItemsCount() {
		return cartItems.size();
	}

	public double getItemsCost() {
		return calculateItemsCost();
	}

	@Override
	public boolean equals(Object o) {
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		Cart cart = (Cart) o;
		return deliveryIncluded == cart.deliveryIncluded &&
			Objects.equals(id, cart.id) &&
			Objects.equals(cartItems, cart.cartItems);
	}

	@Override
	public int hashCode() {
		return Objects.hash(id, cartItems, deliveryIncluded);
	}

	public static class Builder {
		private long id;
		private UserAccount userAccount;
		private List<CartItem> cartItems = new ArrayList<>(0);
		private boolean deliveryIncluded = true;

		public Builder() {
		}

		public Builder(Cart cart) {
			id = cart.id;
			userAccount = cart.userAccount;
			cartItems = cart.cartItems;
			deliveryIncluded = cart.deliveryIncluded;
		}

		public Cart build() {
			Cart cart = new Cart();
			cart.id = id;
			cart.userAccount = userAccount;
			cart.cartItems = cartItems;
			cart.deliveryIncluded = deliveryIncluded;
			return cart;
		}

		public Builder setId(long id) {
			this.id = id;
			return this;
		}

		public Builder setUserAccount(UserAccount userAccount) {
			this.userAccount = userAccount;
			return this;
		}

		public Builder setDeliveryIncluded(boolean deliveryIncluded) {
			this.deliveryIncluded = deliveryIncluded;
			return this;
		}
	}
}

