public abstract class AbstractSorter<T> implements ISorter<T> {

	public static Integer FIRST_PAGE = 1;
	public static Integer PAGE_SIZE_DEFAULT = 2;
	public static Sort.Direction DIRECTION_DEFAULT = Sort.Direction.ASC;

	protected final Map<String, String> sortFieldOptions = new LinkedHashMap<>();
	private final Map<Integer, String> pageSizeOptions = new LinkedHashMap<>();
	private final Map<String, String> directionOptions = new LinkedHashMap<>();
	private Integer pageNumber;
	private Integer pageSize;
	private String sortBy;
	private Sort.Direction sortDirection;

	public AbstractSorter() {
		directionOptions.put(DIRECTION_DEFAULT.toString(), "по возрастанию");
		directionOptions.put(Sort.Direction.DESC.toString(), "по убыванию");

		pageSizeOptions.put(2, "2");
		pageSizeOptions.put(5, "5");
		pageSizeOptions.put(10, "10");
		pageSizeOptions.put(20, "20");
	}

	//-------------------------------------------------------- Обновление опций

	private static Sort.Direction parseSortDirection(String direction) {
		if (direction == null)
			return DIRECTION_DEFAULT;
		return Sort.Direction.fromOptionalString(direction).orElse(DIRECTION_DEFAULT);
	}

	@Override
	public PageRequest updateSorting(SortingValuesDTO values) {
		this.sortBy = (values.getSort() == null) ? getSortFieldDefault() : values.getSort();
		this.pageSize = (values.getSize() == null) ? getDefaultPageSize() : values.getSize();
		this.pageNumber = (values.getPage() == null) ? FIRST_PAGE : values.getPage();
		this.sortDirection = parseSortDirection(values.getDirect());
		return createPageRequest();
	}

	/**
	 * @return кол-во объектов на странице
	 */
	protected int getDefaultPageSize() {
		return PAGE_SIZE_DEFAULT;
	}

	private String getSortFieldDefault() {
		return sortFieldOptions.keySet().iterator().next();
	}

	private PageRequest createPageRequest() {
		return PageRequest.of(
			getPageNumber() - 1,
			getPageSize(),
			getSortDirection(),
			getSortBy());
	}

	//------------------------------------------------------- Подготовка модели

	@Override
	public Model prepareModel(Model model, Page<T> page) {
		preparePagedModel(model, page);
		prepareSortedModel(model);
		prepareFilteredModel(model);
		return model;
	}

	/**
	 * Дополнение модели объектами разбивки на страницы.
	 *
	 * @param model изменяемая модель
	 * @return изменённая модель
	 */
	protected Model preparePagedModel(Model model, Page<T> page) {
		int current = page.getNumber() + 1;
		int begin = Math.max(1, current - 5);
		int end = Math.min(begin + 10, page.getTotalPages());
		model.addAttribute("page", page);
		model.addAttribute("beginIndex", begin);
		model.addAttribute("endIndex", end);
		model.addAttribute("currentIndex", current);
		model.addAttribute("indexesList", IntStream.rangeClosed(begin, end).boxed().collect(toList()));
		return model;
	}

	/**
	 * Дополнение модели объектами сортировки.
	 *
	 * @param model изменяемая модель
	 * @return изменённая модель
	 */
	protected Model prepareSortedModel(Model model) {
		model.addAttribute("pageSizeOptions", getPageSizeOptions());
		model.addAttribute("sortOptions", getSortFieldOptions());
		model.addAttribute("directOptions", getDirectionOptions());
		model.addAttribute("currentPageSize", getPageSize());
		model.addAttribute("currentSort", getSortBy());
		model.addAttribute("currentDirection", getSortDirection().toString());
		return model;
	}

	/**
	 * Дополнение модели объектами фильтрации.
	 *
	 * @param model изменяемая модель
	 * @return изменённая модель
	 */
	protected Model prepareFilteredModel(Model model) {
		return model;
	}

	//---------------------------------------------------- Аксессоры и мутаторы

	public Integer getPageNumber() {
		return pageNumber;
	}

	public Integer getPageSize() {
		return pageSize;
	}

	public String getSortBy() {
		return sortBy;
	}

	public Sort.Direction getSortDirection() {
		return sortDirection;
	}

	public Map<Integer, String> getPageSizeOptions() {
		return pageSizeOptions;
	}

	public Map<String, String> getSortFieldOptions() {
		return sortFieldOptions;
	}

	public Map<String, String> getDirectionOptions() {
		return directionOptions;
	}
}

public class CustomNotValidException extends RuntimeException {
	private static final long serialVersionUID = 4461435547254498698L;

	private final String eventType;
	private final String entityType;
	private final String field;

	public CustomNotValidException(String eventType, String entityType, String field) {
		super();
		this.eventType = eventType;
		this.entityType = entityType;
		this.field = field;
	}

	public FieldError getFieldError() {
		String[] codes = {eventType + "." + field, eventType + "." + entityType + "." + field};
		Object[] arguments = {field};
		return new FieldError(entityType, field, "", false, codes, arguments, "");
	}

	public List<FieldError> getFieldErrors() {
		return Collections.singletonList(getFieldError());
	}

	public String getEntityType() {
		return entityType;
	}
}

@ControllerAdvice(basePackages = "market.rest")
@RestController
public class RestExceptionHandler {
	private static final String ARGUMENT_VALIDATION_CODE = "Error.Validation.Parameter";
	private static final String NOT_EXIST_CODE = "NotExist";

	private static final Logger log = LogManager.getLogger(RestExceptionHandler.class);

	private final MessageSource messageSource;

	public RestExceptionHandler(MessageSource messageSource) {
		this.messageSource = messageSource;
	}

	@ExceptionHandler(Exception.class)
	@ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
	public RestErrorResponse otherExceptions(Exception e, WebRequest request) {
		RestErrorResponse response = new RestErrorResponse(e.getMessage(), request);
		log.error(response.toString(), e);
		return response;
	}

	@ExceptionHandler(AccessDeniedException.class)
	@ResponseStatus(HttpStatus.UNAUTHORIZED)
	public RestErrorResponse accessDeniedException(AccessDeniedException e, WebRequest request) {
		RestErrorResponse response = new RestErrorResponse(e.getMessage(), request);
		log.warn(response.toString());
		return response;
	}

	@ExceptionHandler(UnknownEntityException.class)
	@ResponseStatus(HttpStatus.NOT_FOUND)
	public RestErrorResponse unknownEntityException(UnknownEntityException e, WebRequest request) {
		String entityType = e.getEntityType();
		List<FieldError> fieldErrors = e.getFieldErrors();
		RestErrorResponse response = createLocalizedResponse(NOT_EXIST_CODE, entityType, fieldErrors, request);
		log.warn(response.toString());
		return response;
	}

	@ExceptionHandler(CustomNotValidException.class)
	@ResponseStatus(HttpStatus.NOT_ACCEPTABLE)
	public RestErrorResponse customNotValidException(CustomNotValidException e, WebRequest request) {
		String entityType = e.getEntityType();
		List<FieldError> fieldErrors = e.getFieldErrors();
		RestErrorResponse response = createLocalizedResponse(ARGUMENT_VALIDATION_CODE, entityType, fieldErrors, request);
		log.warn(response.toString());
		return response;
	}

	@ExceptionHandler(MethodArgumentNotValidException.class)
	@ResponseStatus(HttpStatus.NOT_ACCEPTABLE)
	public RestErrorResponse processValidationError(MethodArgumentNotValidException e, WebRequest request) {
		BindingResult result = e.getBindingResult();
		String objectName = result.getObjectName();
		List<FieldError> fieldErrors = result.getFieldErrors();
		RestErrorResponse response = createLocalizedResponse(ARGUMENT_VALIDATION_CODE, objectName, fieldErrors, request);
		log.warn(response.toString());
		return response;
	}

	private RestErrorResponse createLocalizedResponse(String localizationCode, String entityType,
		List<FieldError> fieldErrors, WebRequest request)
	{
		Locale currentLocale = LocaleContextHolder.getLocale();
		String localizedMessage = messageSource.getMessage(localizationCode, null, currentLocale);
		RestErrorResponse response = new RestErrorResponse(localizedMessage, entityType, request);
		return resolveFieldErrors(response, fieldErrors);
	}

	private RestErrorResponse resolveFieldErrors(RestErrorResponse response, List<FieldError> fieldErrors) {
		for (FieldError fieldError : fieldErrors) {
			String localizedErrorMessage = resolveErrorMessage(fieldError);
			response.addFieldError(fieldError.getField(), localizedErrorMessage);
		}
		return response;
	}

	private String resolveErrorMessage(FieldError fieldError) {
		Locale currentLocale = LocaleContextHolder.getLocale();
		String localizedErrorMessage = messageSource.getMessage(fieldError, currentLocale);

		if (localizedErrorMessage.equals(fieldError.getDefaultMessage())) {
			String[] fieldErrorCodes = fieldError.getCodes();
			if (fieldErrorCodes != null)
				localizedErrorMessage = fieldErrorCodes[0];
		}
		return localizedErrorMessage;
	}
}

